  // REAL-TIME SUPABASE SYNC FOR STAFF MEMBERS
  const [fbUser, setFbUser] = useState<any>(null);

  useEffect(() => {
    // Get initial Supabase User
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        setFbUser(session.user);
      } else if (sessionStorage.getItem('supabase_session_bypassed') === 'true') {
        setFbUser({
          email: sessionStorage.getItem('supabase_bypassed_user_email') || 'bypassed@papyruslodge.com',
          id: sessionStorage.getItem('supabase_bypassed_user_id') || 'bypassed-uid'
        });
      } else {
        setFbUser(null);
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setFbUser(session.user);
      } else if (sessionStorage.getItem('supabase_session_bypassed') === 'true') {
        setFbUser({
          email: sessionStorage.getItem('supabase_bypassed_user_email') || 'bypassed@papyruslodge.com',
          id: sessionStorage.getItem('supabase_bypassed_user_id') || 'bypassed-uid'
        });
      } else {
        setFbUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // Protect private pages (including custom portals) with supabase.auth.getSession(). If no session, redirect to /login
  useEffect(() => {
    const protectPages = async () => {
      const isPublicView = activeRole === 'entry' || activeRole === 'customer' || activeRole === 'shader_demo';
      if (!isPublicView) {
        const { data: { session } } = await supabase.auth.getSession();
        const bypassed = sessionStorage.getItem('supabase_session_bypassed') === 'true' || currentUser !== null;
        if (!session && !bypassed) {
          setActiveRole('entry');
          setStaffPortalState('login');
          setLoginModalRole('');
          window.history.pushState({}, '', '/login');
        }
      }
    };
    protectPages();
  }, [activeRole, currentUser]);

  // Handle /login and /admin routing directly with back/forward browser history support
  useEffect(() => {
    const originalPushState = window.history.pushState;
    window.history.pushState = function(...args) {
      originalPushState.apply(this, args);
      setCurrentPath(window.location.pathname);
    };
    
    const handleUrlPath = async () => {
      const path = window.location.pathname;
      setCurrentPath(path);
      
      if (path === '/login') {
        setActiveRole('entry');
        setStaffPortalState('login');
      } else if (path === '/admin') {
        const { data: { session } } = await supabase.auth.getSession();
        const bypassed = sessionStorage.getItem('supabase_session_bypassed') === 'true';
        if (!session && !bypassed) {
          window.history.pushState({}, '', '/login');
          setCurrentPath('/login');
        }
      }
    };
    
    handleUrlPath();
    window.addEventListener('popstate', handleUrlPath);
    return () => {
      window.history.pushState = originalPushState;
      window.removeEventListener('popstate', handleUrlPath);
    };
  }, []);

  useEffect(() => {
    if (!fbUser) return;

    const syncWithSupabase = async () => {
      const uid = fbUser.id || fbUser.uid;
      try {
        const { data, error } = await supabase.from('user_team_members').select('*').eq('userId', uid);
        if (error) throw error;

        if (data && data.length > 0) {
          const listFromSupabase: StaffMember[] = data.map((item: any) => ({
            name: item.name,
            role: (item.role || 'waiter').trim().toLowerCase(),
            phone: item.phone || '',
            active: item.status === 'On Duty' || item.status === 'Active' || item.active || false,
            pin: item.pin || '1234',
            photo: item.photo || item.photoUrl || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',
            accessPrivilege: (item.accessPrivilege || item.role || 'waiter').trim().toLowerCase(),
            username: item.username || item.name.toLowerCase().replace(/\s+/g, '_'),
            password: item.password || item.pin || '1234',
            securityAnswer: item.securityAnswer || 'hawassa',
            hireDate: item.hireDate || '',
            info: item.info || '',
            education: item.education || '',
            certificatePhoto: item.certificatePhoto || '',
            vehicleType: item.vehicleType || undefined,
            plateNumber: item.plateNumber || undefined,
            deliveryZone: item.deliveryZone || undefined,
          }));

          setStaff((prev) => {
            const byKey = new Map<string, StaffMember>();
            for (const s of prev) {
              const key = (s.username || s.name || '').trim().toLowerCase();
              if (key) byKey.set(key, s);
            }
            let changed = false;
            for (const r of listFromSupabase) {
              const key = (r.username || r.name || '').trim().toLowerCase();
              if (!key) continue;
              const existing = byKey.get(key);
              if (!existing) {
                byKey.set(key, r);
                changed = true;
              } else {
                const merged: StaffMember = {
                  ...existing,
                  ...r,
                  vehicleType: r.vehicleType || existing.vehicleType,
                  plateNumber: r.plateNumber || existing.plateNumber,
                  deliveryZone: r.deliveryZone || existing.deliveryZone,
                };
                if (
                  existing.role !== merged.role ||
                  existing.accessPrivilege !== merged.accessPrivilege ||
                  existing.pin !== merged.pin ||
                  existing.password !== merged.password ||
                  existing.username !== merged.username
                ) {
                  byKey.set(key, merged);
                  changed = true;
                }
              }
            }
            return changed ? Array.from(byKey.values()) : prev;
          });
        } else {
          // Supabase database is empty for this user, seed current local staff to Supabase
          const formatPayloads = staff.map(s => ({
            id: 'st-' + Math.random().toString(36).substr(2, 9),
            userId: uid,
            name: s.name,
            email: (s.username || s.name.toLowerCase().replace(/\s+/g, '_')) + '@papyruslodge.com',
            phone: s.phone || '',
            role: s.role,
            status: s.active ? 'On Duty' : 'Active',
            pin: s.pin || '1234',
            active: s.active || false,
            photo: s.photo || '',
            accessPrivilege: s.accessPrivilege || s.role,
            username: s.username || s.name.toLowerCase().replace(/\s+/g, '_'),
            password: s.password || s.pin || '1234',
            securityAnswer: s.securityAnswer || 'hawassa',
            hireDate: s.hireDate || '',
            info: s.info || '',
            education: s.education || '',
            certificatePhoto: s.certificatePhoto || '',
            createdAt: new Date().toISOString()
          }));

          await supabase.from('user_team_members').upsert(formatPayloads);
        }
      } catch (err) {
        console.warn("Supabase user_team_members loading/syncing failed, falling back to local list:", err);
      }
    };

    syncWithSupabase();
  }, [fbUser]);

  // Unlock Web Audio on first user interaction for instant staff/manager alert sounds
  useEffect(() => {
    initAudioUnlock();
  }, []);

  // HANDLERS FOR STAFF KEYPAD VERIFICATIONS
  const playVoiceAlert = (message: string) => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();
      
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(800, audioCtx.currentTime); 
      gainNode.gain.setValueAtTime(0.25, audioCtx.currentTime);
      
      oscillator.start();
      setTimeout(() => {
        oscillator.stop();
        audioCtx.close();
      }, 250);

      if ('speechSynthesis' in window) {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(message);
        utterance.rate = 1.0;
        utterance.pitch = 1.05;
        utterance.volume = 1.0;
        window.speechSynthesis.speak(utterance);
      }
    } catch (err) {
      console.warn("Speech voice audio blocked or disabled", err);
    }
  };

  // Ref to track seen active assistance call IDs, Chef Pending orders, and triggered Kitchen pickup alert IDs
  const seenActiveCallIdsRef = useRef<string[]>([]);
  const seenChefOrderIdsRef = useRef<Set<string> | null>(null);
  const triggeredPickupAlertIdsRef = useRef<Set<string> | null>(null);

  const getKitchenPickupAlertId = (orderId: string) =>
    `pickup-${orderId.replace(/^#/, '').trim()}`;

  // Trigger Chef new-order alert immediately when a new Pending order arrives in Kitchen Queue
  useEffect(() => {
    if (!hasLoadedCloudSettings) return;

    const pendingOrders = orders.filter((o) => {
      const stage = getEffectiveCookingStatus(o);
      return stage === 'Pending';
    });

    if (seenChefOrderIdsRef.current === null) {
      seenChefOrderIdsRef.current = new Set(pendingOrders.map((o) => o.id));
      return;
    }

    const newlyArrived = pendingOrders.filter((o) => !seenChefOrderIdsRef.current!.has(o.id));
    pendingOrders.forEach((o) => seenChefOrderIdsRef.current!.add(o.id));

    if (newlyArrived.length === 0 || activeRole !== 'chef') return;

    const accessibleNew = newlyArrived.filter((o) =>
      isSupervisorRole(currentUser)
        ? true
        : canStaffAccessOrder(currentUser, o, shiftAssignments, tableAssignments).allowed
    );
    if (accessibleNew.length === 0) return;

    const latest = accessibleNew[0];
    playChefNewOrderAlertSound(latest.id, latest.location);
    setChefNewOrderToast(
      `🛎️ ${latest.id} · ${latest.location} (${latest.items.length} items) — ${
        latest.status === 'Paid' ? 'PAID ✓' : latest.payment.toUpperCase()
      }`
    );
    window.setTimeout(() => {
      setChefNewOrderToast((curr) => (curr && curr.includes(latest.id) ? null : curr));
    }, 8000);
  }, [orders, activeRole, hasLoadedCloudSettings, currentUser, shiftAssignments, tableAssignments]);

  // Trigger audio + voice alert immediately on Waiter Portal (or staff portals) when a customer calls or kitchen completes food
  useEffect(() => {
    if (!hasLoadedCloudSettings) return;

    const currentActiveIds = assistanceCalls.filter(c => c.active).map(c => c.id);
    const newActiveCalls = assistanceCalls.filter(
      c => c.active && !seenActiveCallIdsRef.current.includes(c.id)
    );
    seenActiveCallIdsRef.current = Array.from(new Set([...seenActiveCallIdsRef.current, ...currentActiveIds]));

    const isStaffRole = ['waiter', 'chef', 'delivery', 'admin', 'manager', 'receptionist', 'cashier', 'guard'].includes(activeRole);
    if (newActiveCalls.length === 0 || !isStaffRole) return;

    const myName = (currentUser?.name || '').trim().toLowerCase();
    const isSup = isSupervisorRole(currentUser);

    newActiveCalls.forEach(call => {
      if (activeRole === 'waiter') {
        if (call.type === 'new_order' || call.targetRole === 'chef' || call.targetRole === 'delivery') return;
        const assignedTarget = (call.targetWaiter || getAssignedWaiterForTable(call.location) || '').trim().toLowerCase();
        const shouldAlertThisWaiter = isSup || !assignedTarget || !myName || assignedTarget === myName;
        if (shouldAlertThisWaiter) {
          if (call.type === 'pickup') {
            playKitchenReadyForWaiterAlertSound(
              call.orderId || call.id,
              call.location,
              call.targetWaiter || undefined
            );
          } else {
            playWaiterCallAlertSound(call.location, call.targetWaiter, call.reason || call.message);
          }
        }
      } else if (activeRole === 'delivery') {
        if (call.targetRole === 'delivery' || (call.type === 'pickup' && (!call.targetWaiter || call.targetWaiter.toLowerCase() === myName))) {
          playKitchenReadyForWaiterAlertSound(
            call.orderId || call.id,
            call.location,
            call.targetWaiter || currentUser?.name || 'Delivery Courier'
          );
        }
      } else if (activeRole === 'chef') {
        // Chef order alerts are handled cleanly by the pending-orders effect above
        return;
      } else if (call.type !== 'call' && call.type !== 'new_order') {
        playVoiceAlert(`Notification! Kitchen pickup or assistance alert from ${call.location}!`);
      }
    });
  }, [assistanceCalls, activeRole, hasLoadedCloudSettings, currentUser, shiftAssignments, tableAssignments]);

  // Automatically trigger a unique 'pickup' notification to the assigned waiter whenever any dish order transitions to 'Completed'
  useEffect(() => {
    if (!hasLoadedCloudSettings) return;

    if (triggeredPickupAlertIdsRef.current === null) {
      const initialIds = new Set<string>();
      orders.forEach((o) => {
        const stage = getEffectiveCookingStatus(o);
        if (stage === 'Completed' || stage === 'Served') {
          initialIds.add(getKitchenPickupAlertId(o.id));
        }
      });
      assistanceCalls.forEach((c) => {
        if (c.type === 'pickup') {
          initialIds.add(c.id);
          if (c.orderId) initialIds.add(getKitchenPickupAlertId(c.orderId));
        }
      });
      triggeredPickupAlertIdsRef.current = initialIds;
      return;
    }

    const activePickupIds = new Set(
      assistanceCalls
        .filter((c) => c.active !== false && c.type === 'pickup')
        .flatMap((c) => [c.id, ...(c.orderId ? [getKitchenPickupAlertId(c.orderId)] : [])])
    );

    const nowMs = Date.now();
    const timeNow = new Date(nowMs).toLocaleTimeString('en-US', {
      hour12: false,
      hour: '2-digit',
      minute: '2-digit',
    });

    orders.forEach((ord) => {
      const stage = getEffectiveCookingStatus(ord);
      const pickupId = getKitchenPickupAlertId(ord.id);

      if (stage === 'Pending' || stage === 'Preparing') {
        triggeredPickupAlertIdsRef.current!.delete(pickupId);
        return;
      }

      if (stage === 'Completed' && !ord.servedByWaiter) {
        if (activePickupIds.has(pickupId) || triggeredPickupAlertIdsRef.current!.has(pickupId)) {
          return;
        }

        triggeredPickupAlertIdsRef.current!.add(pickupId);
        resolveOrderAssistanceCalls(ord.id, currentUser?.name, ['new_order']);

        if (ord.orderType === 'delivery') {
          if (ord.deliveryStatus === 'Delivered') return;
          addAssistanceCall({
            id: pickupId,
            orderId: ord.id,
            location: ord.deliveryAddress || ord.location,
            time: timeNow,
            active: true,
            type: 'pickup',
            targetRole: 'delivery',
            targetWaiter: ord.deliveryDriverName || undefined,
            createdAt: nowMs,
            message: `🛵 የዴሊቨሪ ምግብ ${ord.id} (${ord.deliveryAddress || ord.location}) ከኩሽና ተዘጋጅቷል! (Delivery Ready for Dispatch)`,
          });
          return;
        }

        const resolvedWaiter =
          (!isGenericWaiterLabel(ord.waiter) ? ord.waiter : '') ||
          getAssignedWaiterForTable(ord.location) ||
          undefined;

        addAssistanceCall({
          id: pickupId,
          orderId: ord.id,
          location: ord.location,
          time: timeNow,
          active: true,
          type: 'pickup',
          targetRole: 'waiter',
          targetWaiter: resolvedWaiter,
          createdAt: nowMs,
          message: resolvedWaiter
            ? `🍲 ${resolvedWaiter} — ${ord.location} (${ord.id}) ተሰርቶ አልቋል! እባክዎ ቼክ አድርገው ለደንበኛው ያድርሱ! (Ready for Pickup)`
            : `🍲 ${ord.id} (${ord.location}) ተሰርቶ አልቋል — ቼክ አድርገው ለደንበኛው ያድርሱ! (Ready from Kitchen)`,
        });
      }
    });
  }, [orders, assistanceCalls, hasLoadedCloudSettings, shiftAssignments, tableAssignments]);

  // Ref to track seen stock alert log IDs so Manager gets immediate Audio + Push notifications only for NEW out-of-stock events
  const seenStockAlertIdsRef = useRef<Set<string> | null>(null);

  useEffect(() => {
    if (!hasLoadedCloudSettings) return;

    if (seenStockAlertIdsRef.current === null) {
      seenStockAlertIdsRef.current = new Set(stockAlertLogs.map((l) => l.id));
      return;
    }

    const newOutEvents = stockAlertLogs.filter(
      (l) => !seenStockAlertIdsRef.current!.has(l.id) && !l.newAvailable
    );
    stockAlertLogs.forEach((l) => seenStockAlertIdsRef.current!.add(l.id));

    if (newOutEvents.length === 0) return;
    const isManagerPortal = activeRole === 'manager' || activeRole === 'admin';
    if (!isManagerPortal) return;

    newOutEvents.forEach((ev) => {
      const displayName = appLang === 'am' || appLang === 'ti' ? ev.itemNameAm : ev.itemNameEn || ev.itemNameAm;
      if (stockAlertSettings.audioEnabled) {
        playStockOutAlertSound(ev.itemNameEn || ev.itemNameAm, ev.changedByName);
      }
      if (stockAlertSettings.pushEnabled) {
        sendBrowserPushNotification(
          `🔴 OUT OF STOCK: ${displayName}`,
          `${ev.changedByName} (${ev.changedByRole}) marked "${ev.itemNameAm}" out of stock at ${ev.time}.`,
          `stock-out-${ev.id}`
        );
      }
    });
  }, [stockAlertLogs, activeRole, hasLoadedCloudSettings, stockAlertSettings, appLang]);

  const renderWiFiClockInWidget = () => {
    if (!currentUser) return null;
    const todayDate = getLocalTodayIso();

    const clockedInToday = attendance.some(
      (a) =>
        a.staffName === currentUser.name &&
        normalizeRecordDateToIso(a.date) === todayDate &&
        (a.status === 'Present' || a.status === 'Late')
    );
    const pendingRequest = pendingAttendanceRequests.find(
      (r) =>
        r.staffName === currentUser.name &&
        (normalizeRecordDateToIso(r.time) || r.time) === todayDate &&
        r.status === 'pending'
    );
    const rejectedRequest = pendingAttendanceRequests.find(
      (r) =>
        r.staffName === currentUser.name &&
        (normalizeRecordDateToIso(r.time) || r.time) === todayDate &&
        r.status === 'rejected'
    );

    if (clockedInToday) {
      return (
        <div className="bg-emerald-50 border border-emerald-300 p-4 rounded-2xl flex items-center justify-between shadow-sm">
          <div className="flex items-center gap-3">
            <span className="text-xl">📶</span>
            <div>
              <p className="text-[10px] text-emerald-700 font-mono font-black uppercase tracking-wider">PAPYRUS SECURE LODGE WIFI</p>
              <h5 className="text-xs font-black text-emerald-950">
                {tText({ am: 'ክሎክ-ኢን ተረጋግጧል', en: 'CLOCK-IN APPROVED', or: 'Seensi Mirkanaa\'e', ti: 'ክሎክ-ኢን ተረጋጊጹ', sid: 'Seena Buuxantino', fr: 'POINTAGE APPROUVÉ', de: 'STEMPELN GENEHMIGT', it: 'TIMBRATURA APPROVATA', zh: '打卡已批准', ar: 'تم اعتماد الحضور' })}
              </h5>
            </div>
          </div>
          <span className="bg-emerald-600 text-white text-[9px] font-mono uppercase font-black px-2.5 py-1 rounded-lg shadow-xs">
            ONLINE ✔
          </span>
        </div>
      );
    }

    return (
      <div className="bg-white border border-stone-200 p-5 rounded-2xl relative overflow-hidden space-y-4 shadow-sm">
        <div className="flex justify-between items-start gap-3 flex-wrap">
          <div className="space-y-0.5">
            <span className="text-[9px] text-[#b21f1f] font-mono font-black tracking-widest uppercase block">ATTENDANCE VERIFICATION ENGINE</span>
            <h4 className="text-sm font-black text-stone-900 uppercase">
              📶 {tText({ am: 'የእለት ተእለት የስራ መግቢያ ማረጋገጫ (WiFi Clock-In)', en: 'Daily WiFi Shift Clock-In', or: 'Mirkaneessa Seensa Hojii WiFi', ti: 'ዕለታዊ WiFi መእተዊ ሰራሕተኛ', sid: 'Barru WiFi Looso Seena', fr: 'Pointage WiFi Quotidien', de: 'Täglicher WiFi-Schicht-Check-In', it: 'Timbratura WiFi Giornaliera', zh: '每日 WiFi 上班打卡', ar: 'تسجيل الحضور اليومي عبر WiFi' })}
            </h4>
            <p className="text-[11px] text-stone-600 leading-relaxed font-semibold">
              {tText({ am: 'በድርጅቱ ዋይፋይ (Lodge Corporate WiFi) ሲገናኙ ብቻ መመዝገብ ይችላሉ።', en: 'Connect to Lodge Corporate WiFi to submit your attendance clock-in.', or: 'WiFi Dhaabbatichaatti yoo walqunnamtan qofa galmaa\'uu dandeessu.', ti: 'ብWiFi እቲ ትካል ክትራኸቡ ከለኹም ጥራይ ክትምዝገቡ ትኽእሉ።', sid: 'Looje WiFi ledo xaadduro calla borreesa dandiinanni.', fr: 'Connectez-vous au WiFi du Lodge pour pointer votre prise de service.', de: 'Mit dem Lodge-WLAN verbinden, um einzuchecken.', it: 'Connettiti al WiFi del Lodge per registrare l\'ingresso.', zh: '连接度假村企业 WiFi 后即可打卡上班。', ar: 'اتصل بشبكة WiFi الخاصة بالمنتجع لتسجيل الحضور.' })}
            </p>
          </div>
          <div className="flex flex-col items-end font-mono text-[9px]">
            <span className="text-emerald-700 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded font-bold flex items-center gap-1">
              PAPYRUS_LODGE_SECURE
            </span>
            <span className="text-stone-500 mt-1">IP: 192.168.43.32 (MATCHED Whitelist)</span>
          </div>
        </div>

        {pendingRequest ? (
          <div className="bg-amber-50 border border-amber-300 p-3 text-center rounded-xl space-y-1">
            <div className="flex items-center justify-center gap-2 text-amber-800 font-bold text-xs">
              <span>⏳</span>
              <span>{tText({ am: 'የማሳወቂያ ጥያቄ ተልኳል (በመጠባበቅ ላይ)', en: 'PENDING MANAGER APPROVAL', or: 'Eeyyama Hoggansaa Eegaa Jira', ti: 'ፍቓድ ማናጀር ይጽበ ኣሎ', sid: 'Massagaanchu Fajjo Keerinnanni No', fr: 'EN ATTENTE DE VALIDATION', de: 'WARTET AUF FREIGABE', it: 'IN ATTESA DI APPROVAZIONE', zh: '等待经理审批', ar: 'في انتظار موافقة المدير' })}</span>
            </div>
            <p className="text-[10px] text-amber-900/80">
              {tText({ am: 'እባክዎ ማናጀሩ ጥያቄዎን እስኪያፀድቁ ድረስ ይጠብቁ።', en: 'Please wait while the manager reviews and approves your clock-in.', or: 'Maaloo hanga hoggantoonni mirkaneessan eegaa.', ti: 'በጃኹም ማናጀር ክሳብ ዘጽድቖ ተጸበዩ።', sid: 'Maaloo massagaanchu fajjeeshsha keeri.', fr: 'Veuillez patienter pendant que le responsable approuve votre pointage.', de: 'Bitte warten Sie, bis der Manager Ihre Anfrage bestätigt.', it: 'Attendi mentre il manager approva la timbratura.', zh: '请等待经理审核批准您的打卡请求。', ar: 'يرجى الانتظار حتى يوافق المدير على طلبك.' })}
            </p>
          </div>
        ) : (
          <div className="flex flex-col sm:flex-row gap-3 items-center justify-between border-t border-stone-200 pt-3">
            <div className="text-left">
              <span className="text-[9px] text-stone-500 block font-mono uppercase font-bold">
                {tText({
                  am: 'የመሣሪያ ግንኙነት ሁኔታ:',
                  en: 'DEVICE CONNECTION STATUS:',
                  or: 'HAALA WALQUNNAMTII:',
                  ti: 'ኩነታት መርበብ:',
                  sid: 'XAADDO GARA:',
                  fr: 'STATUT DE CONNEXION :',
                  de: 'VERBINDUNGSSTATUS:',
                  it: 'STATO CONNESSIONE:',
                  zh: '设备连接状态：',
                  ar: 'حالة الاتصال:',
                })}
              </span>
              <p className="text-xs font-bold text-emerald-700 flex items-center gap-1.5">
                <span>
                  📶 {tText({
                    am: 'ተገናኝቷል (CONNECTED)',
                    en: 'CONNECTED',
                    or: 'WALQUNNAMEERA',
                    ti: 'ተራኺቡ ኣሎ',
                    sid: 'XAADINO',
                    fr: 'CONNECTÉ',
                    de: 'VERBUNDEN',
                    it: 'CONNESSO',
                    zh: '已连接',
                    ar: 'متصل',
                  })}
                </span>
                <span className="text-[10px] text-stone-600 font-normal font-sans">
                  {tText({
                    am: '(ሲግናል፡ እጅግ በጣም ጥሩ፣ ማረጋገጫ አልፏል)',
                    en: '(Signal: Perfect, Whitelist Verification Passed)',
                    or: '(Mallattoo: Baay’ee Gaarii, Mirkanaa’eera)',
                    ti: '(ሲግናል፡ ብሉጽ፣ ምርግጋጽ ሓሊፉ)',
                    sid: '(Siignaale: Dancha, Buuxantino)',
                    fr: '(Signal : Excellent, vérifié)',
                    de: '(Signal: Perfekt, verifiziert)',
                    it: '(Segnale: Ottimo, verificato)',
                    zh: '(信号极佳，白名单验证通过)',
                    ar: '(الإشارة ممتازة، تم التحقق)',
                  })}
                </span>
              </p>
            </div>
            
            <button
              onClick={() => {
                const newReq = {
                  id: 'att-req-' + Date.now(),
                  staffName: currentUser.name,
                  role: currentUser.role,
                  time: todayDate,
                  wifiSsid: 'PAPYRUS_LODGE_SECURE',
                  status: 'pending' as const
                };
                setPendingAttendanceRequests(prev => [newReq, ...prev]);
                playVoiceAlert(`Clock-in request submitted for ${currentUser.name}. Waiting for manager approval.`);
                showAppToast(`🎉 የዋይፋይ ክሎክ-ኢን ጥያቄ በተሳካ ሁኔታ ተልኳል! ማናጀሩ ሲያፀድቁት ሙሉ በሙሉ ይንቀሳቀሳሉ።`);
              }}
              className="w-full sm:w-auto bg-[#b21f1f] hover:bg-[#8c1414] text-white font-black text-xs uppercase px-5 py-2.5 font-mono cursor-pointer transition-all border-b-2 border-[#f4c22b] shadow-md rounded-xl"
            >
              🔐 CLOCK IN (ማረጋገጫ ደውል)
            </button>
          </div>
        )}

        {rejectedRequest && (
          <p className="text-[10.5px] text-red-400 text-center font-bold">
            ⚠️ ቀዳሚው ጥያቄ በትክክል ባለመገናኘቱ ውድቅ ተደርጓል። እባክዎ እንደገና ይሞክሩ።
          </p>
        )}
      </div>
    );
  };

  // VISTOR LOG / GUARD GATEWAY ACTIONS
  const handleAddVisitor = (e: React.FormEvent) => {
    e.preventDefault();
    if (!gName.trim()) {
      showAppToast("⚠️ እባክዎ የእንግዳውን ስም ያስገቡ!");
      return;
    }
    const autoTag = gTicketTag.trim() || `TAG-#${100 + visitorLog.length + 1}`;
    const newVisitor: VisitorLog = {
      id: 'v-' + Date.now(),
      name: gName.trim(),
      phone: gPhone.trim() || 'ያልተገለጸ',
      carPlate: gPlate.trim() || 'ያልተገለጸ',
      purpose: gPurpose,
      vehicleType: gVehicleType,
      ticketTagNumber: autoTag,
      timeIn: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' ' + new Date().toLocaleDateString(),
      status: 'In Lodge',
      registeredByGuard: currentUser?.name || 'አቶ ዳዊት (ጥበቃ)',
      registeredByRole: currentUser?.role || 'guard'
    };
    setVisitorLog([newVisitor, ...visitorLog]);
    setGName('');
    setGPhone('');
    setGPlate('');
    setGTicketTag('');
    setSelectedTicketPassVisitor(newVisitor);
    showAppToast(`👮 የፓርኪንግና የእንግዳ መግቢያ ተመዝግቧል! 🎫 ካርድ: ${autoTag}`, 5500);
  };

  const handleCheckoutVisitor = (v: VisitorLog) => {
    setCheckoutConfirmVisitor(v);
  };

  const confirmExitCheckout = (v: VisitorLog) => {
    setVisitorLog(prevLog => prevLog.map(item => item.id === v.id ? {
      ...item,
      status: 'Checked Out',
      verifiedByGuard: currentUser?.name || 'Guard Gate',
      timeOut: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' ' + new Date().toLocaleDateString()
    } : item));
    setCheckoutConfirmVisitor(null);
    setExitToastMessage(`🚪 ተረክቦ ወጥቷል! የመውጫ ማረጋገጫ ተጠናቋል። የፓርኪንግ ካርድ ${v.ticketTagNumber || 'TAG-#101'} ተመልሷል።`);
    setTimeout(() => setExitToastMessage(''), 6000);
  };

  const directInstantCheckout = (v: VisitorLog) => {
    setVisitorLog(prevLog => prevLog.map(item => item.id === v.id ? {
      ...item,
      status: 'Checked Out',
      verifiedByGuard: currentUser?.name || 'Guard Gate',
      timeOut: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' ' + new Date().toLocaleDateString()
    } : item));
    setExitToastMessage(`🚪 ተረክቦ ወጥቷል! የመውጫ ማረጋገጫ ተጠናቋል። የፓርኪንግ ካርድ ${v.ticketTagNumber || 'TAG-#101'} ተመልሷል።`);
    setTimeout(() => setExitToastMessage(''), 6000);
  };

  const handleDeleteVisitor = (id: string) => {
    askConfirmAndRun('እርግጠኛ ነዎት ይህንን የጎብኚ መዝገብ መሰረዝ ይፈልጋሉ? (Are you sure you want to delete this visitor record?)', () => {
      setVisitorLog(visitorLog.filter(v => v.id !== id));
      showAppToast('🗑️ የጎብኚው መዝገብ ተሰርዟል።');
    });
  };

  const handleSuccessLogin = (matchedStaff: StaffMember) => {
    setCurrentUser(matchedStaff);
    try {
      sessionStorage.setItem('supabase_session_bypassed', 'true');
      sessionStorage.setItem('supabase_bypassed_current_user', JSON.stringify(matchedStaff));
    } catch {}
    setIsStaffAuthModalOpen(false);
    const rawPriv = matchedStaff.accessPrivilege && matchedStaff.accessPrivilege.trim().toLowerCase() !== 'none'
      ? matchedStaff.accessPrivilege
      : matchedStaff.role;
    const privilege = (rawPriv || '').trim().toLowerCase();
    if (!privilege || privilege === 'none') {
      showAppToast('🔒 ይህ መለያ የሲስተም መዳረሻ ፈቃድ የለውም! እባክዎ አስኪያጅን (Admin) ያነጋግሩ።');
      return;
    }
    setActiveRole(privilege);
  };

  const handleUnifiedLoginSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setUnifiedError('');

    if (unifiedMethod === 'password') {
      const enteredUserLower = unifiedUsername.trim().toLowerCase();
      const enteredPass = unifiedPassword.trim();
      if (!enteredUserLower || !enteredPass) {
        setUnifiedError('እባክዎ መግቢያ ስምና የይለፍ ቃል በትክክል ያስገቡ! (Please enter username/password)');
        return;
      }

      // Check local staff credentials first - if match, bypass Supabase to prevent any email confirmation blockages
      const matchedLocalStaff = staff.find(s =>
        ((s.username || '').trim().toLowerCase() === enteredUserLower ||
         s.name.trim().toLowerCase() === enteredUserLower) &&
        ((s.password || s.pin || '').trim() === enteredPass)
      );

      if (matchedLocalStaff) {
        sessionStorage.setItem('supabase_session_bypassed', 'true');
        sessionStorage.setItem('supabase_bypassed_user_email', `${enteredUserLower}@papyruslodge.com`);
        sessionStorage.setItem('supabase_bypassed_user_id', 'bypassed-local-uid');
        sessionStorage.setItem('supabase_bypassed_current_user', JSON.stringify(matchedLocalStaff));
        handleSuccessLogin(matchedLocalStaff);
        setUnifiedUsername('');
        setUnifiedPassword('');
        setUnifiedError('');
        setStaffPortalState('welcome');
        window.history.pushState({}, '', '/');
        return;
      }

      // Convert username/email entry to valid Supabase email format
      const targetEmail = unifiedUsername.trim().includes('@') 
        ? unifiedUsername.trim() 
        : `${enteredUserLower.replace(/\s+/g, '_')}@papyruslodge.com`;

      try {
        // ---- Supabase Sign In with Password ----
        const { data, error } = await supabase.auth.signInWithPassword({
          email: targetEmail,
          password: enteredPass
        });

        let isBypassed = false;
        let finalUserEmail = targetEmail;
        let finalUserId = 'bypassed-uid';

        if (error) {
          const errMsg = error.message.toLowerCase();
          const isUnconfirmed = 
            errMsg.includes('confirm') || 
            errMsg.includes('verify') || 
            errMsg.includes('verification') || 
            errMsg.includes('unconfirmed') || 
            errMsg.includes('not confirmed') ||
            errMsg.includes('email not') ||
            errMsg.includes('check your email') ||
            errMsg.includes('email_not_confirmed');

          if (isUnconfirmed) {
            isBypassed = true;
          } else {
            setUnifiedError(error.message);
            return;
          }
        }

        if (!data.session && !isBypassed) {
          if (data.user) {
            isBypassed = true;
            finalUserEmail = data.user.email || targetEmail;
            finalUserId = data.user.id;
          } else {
            // Since we want to bypass email confirmation, if they signed up we can log them in anyway!
            isBypassed = true;
          }
        }

        if (isBypassed) {
          sessionStorage.setItem('supabase_session_bypassed', 'true');
          sessionStorage.setItem('supabase_bypassed_user_email', finalUserEmail);
          sessionStorage.setItem('supabase_bypassed_user_id', finalUserId);
        }

        // Auto-identify the team member by their custom username & password combination!
        const matched = staff.find(s => 
          ((s.username || '').trim().toLowerCase() === enteredUserLower) ||
          (s.name.trim().toLowerCase() === enteredUserLower)
        );

        setUnifiedUsername('');
        setUnifiedPassword('');
        setUnifiedError('');

        let loggedInStaff = matched;
        const normalizedUnifiedRole = (unifiedRole || 'waiter').trim().toLowerCase();
        if (matched) {
          handleSuccessLogin(matched);
        } else {
          // Fallback user matching active role
          const genericStaff: StaffMember = {
            name: (data.user?.email || finalUserEmail).split('@')[0] || 'Staff Member',
            role: normalizedUnifiedRole,
            accessPrivilege: normalizedUnifiedRole,
            pin: '1234',
            active: true,
            photo: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',
            phone: '',
            username: enteredUserLower,
            password: enteredPass
          };
          loggedInStaff = genericStaff;
          sessionStorage.setItem('supabase_session_bypassed', 'true');
          sessionStorage.setItem('supabase_bypassed_current_user', JSON.stringify(genericStaff));
          setCurrentUser(genericStaff);
          setActiveRole(normalizedUnifiedRole);
        }

        if (loggedInStaff) {
          sessionStorage.setItem('supabase_bypassed_current_user', JSON.stringify(loggedInStaff));
        }

        setStaffPortalState('welcome');
        window.history.pushState({}, '', '/');
      } catch (err: any) {
        setUnifiedError(err.message || 'እንቅስቃሴው አልተሳካም። (Authentication failed)');
      }
    } else {
      const pinTrim = unifiedPin.trim();
      const targetRoleNorm = (unifiedRole || '').trim().toLowerCase();
      if (pinTrim.length !== 4) {
        setUnifiedError('እባክዎ ባለ 4 አሃዝ ፒን ያስገቡ። (Please enter a 4-digit PIN)');
        return;
      }
      // Auto-identify by the secure 4-digit PIN and matching selected role (unifiedRole)
      const matched = staff.find(s =>
        (s.pin || '').trim() === pinTrim &&
        ((s.role || '').trim().toLowerCase() === targetRoleNorm ||
         (s.accessPrivilege || '').trim().toLowerCase() === targetRoleNorm)
      );
      if (matched) {
        setUnifiedPin('');
        setUnifiedError('');
        handleSuccessLogin(matched);
        
        setStaffPortalState('welcome');
        window.history.pushState({}, '', '/');
      } else {
        const pinExistsAnywhere = staff.some(s => (s.pin || '').trim() === pinTrim);
        if (pinExistsAnywhere) {
          setUnifiedError('የተሳሳተ የፒን ቁጥር ለተመረጠው የስራ ዘርፍ! (Incorrect PIN for the selected division!)');
        } else {
          setUnifiedError('የተሳሳተ የፒን ቁጥር! (Incorrect PIN)');
        }
        setUnifiedPin('');
      }
    }
  };

  const handleStaffSignUpSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setUnifiedError('');
    setSignupSuccessMessage('');

    if (!signupName.trim()) {
      setUnifiedError('እባክዎ የሙሉ ስም በትክክል ያስገቡ! (Please enter Full Name)');
      return;
    }
    if (!signupUsername.trim()) {
      setUnifiedError('እባክዎ መግቢያ ስም በትክክል ያስገቡ! (Please enter Username)');
      return;
    }
    if (!signupPassword.trim()) {
      setUnifiedError('እባክዎ የይለፍ ቃል በትክክል ያስገቡ! (Please enter Password)');
      return;
    }
    if (signupPassword !== signupConfirmPassword) {
      setUnifiedError('የይለፍ ቃሎች አይዛመዱም! (Passwords do not match)');
      return;
    }
    if (!signupPin.trim() || signupPin.length !== 4 || isNaN(Number(signupPin))) {
      setUnifiedError('የይለፍ ፒን ቁጥር 4 አሃዝ ብቻ መሆን አለበት! (PIN must be exactly 4 digits)');
      return;
    }
    if (!signupSecurityAnswer.trim()) {
      setUnifiedError('እባክዎ የምስጢር ጥያቄ መልስ ያስገቡ! (Please enter security answer for recovery)');
      return;
    }

    const normUsername = signupUsername.trim().toLowerCase().replace(/\s+/g, '_');
    const isTaken = staff.some(s => s.username?.toLowerCase() === normUsername);
    if (isTaken) {
      setUnifiedError('ይህ መግቢያ ስም ቀድሞ ተይዟል! እባክዎ ሌላ ይሞክሩ (Username already taken!)');
      return;
    }

    // Convert to valid Supabase email standard
    const targetEmail = signupUsername.trim().includes('@')
      ? signupUsername.trim()
      : `${normUsername}@papyruslodge.com`;

    try {
      // ---- Supabase Sign Up ----
      const { data, error } = await supabase.auth.signUp({
        email: targetEmail,
        password: signupPassword.trim()
      });

      if (error) {
        setUnifiedError(error.message);
        return;
      }

      const normalizedSignupRole = (signupRole || 'waiter').trim().toLowerCase();
      const newStaff: StaffMember = {
        name: signupName.trim(),
        role: normalizedSignupRole,
        accessPrivilege: normalizedSignupRole,
        pin: signupPin.trim(),
        active: true,
        photo: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100',
        phone: '',
        username: normUsername,
        password: signupPassword.trim(),
        securityAnswer: signupSecurityAnswer.trim().toLowerCase()
      };

      // Always keep local/cloud-synced staff list updated immediately (prevents missing login on newly registered roles)
      setStaff(prev => [...prev.filter(s => (s.username || '').trim().toLowerCase() !== normUsername), newStaff]);
      if (normalizedSignupRole === 'delivery') {
        setDeliveryDriverStates(prev => [
          ...prev.filter(d => d.staffName.trim().toLowerCase() !== newStaff.name.toLowerCase()),
          { staffName: newStaff.name, status: 'available', completedTrips: 0, updatedAt: Date.now() },
        ]);
      }

      const targetUser = data.user;
      if (targetUser) {
        const uid = targetUser.id;
        const memberId = 'st-' + Math.random().toString(36).substr(2, 9);
        const memberPayload = {
          id: memberId,
          userId: uid,
          name: newStaff.name,
          email: targetEmail,
          phone: '',
          role: newStaff.role,
          status: 'Active',
          pin: newStaff.pin,
          active: true,
          photo: newStaff.photo,
          accessPrivilege: newStaff.accessPrivilege,
          username: newStaff.username,
          password: newStaff.password,
          securityAnswer: newStaff.securityAnswer,
          createdAt: new Date().toISOString()
        };
        supabase.from('user_team_members').insert([memberPayload]).then(({ error: insErr }) => {
          if (insErr) console.warn('Supabase user_team_members insert note:', insErr);
        });
      }

      // Bypass email confirmation requirement on sign up
      sessionStorage.setItem('supabase_session_bypassed', 'true');
      sessionStorage.setItem('supabase_bypassed_user_email', targetEmail);
      if (targetUser) {
        sessionStorage.setItem('supabase_bypassed_user_id', targetUser.id);
        setFbUser(targetUser);
      }
      sessionStorage.setItem('supabase_bypassed_current_user', JSON.stringify(newStaff));

      setCurrentUser(newStaff);
      setActiveRole(normalizedSignupRole);

      showAppToast(`🎉 ሠራተኛው ${newStaff.name} በስኬት ተመዝግቧል! (Staff user registered successfully!)`);
      
      // Clear signup fields
      setSignupName('');
      setSignupUsername('');
      setSignupPassword('');
      setSignupConfirmPassword('');
      setSignupPin('');
      setSignupSecurityAnswer('');
      
      // Redirect page to the Home page ('/')
      setStaffPortalState('welcome');
      window.history.pushState({}, '', '/');
    } catch (err: any) {
      console.error("Staff sign up failure: ", err);
      setUnifiedError(err.message || 'ምዝገባው አልተሳካም፤ እባክዎ እንደገና ይሞክሩ። (Sign up failed!)');
    }
  };

  const handleResetCredentials = async (name: string, pin: string, password?: string, username?: string) => {
    const cleanName = name.trim().toLowerCase();
    const targetUsername = (username || name.trim().toLowerCase().replace(/\s+/g, '_')).trim().toLowerCase();
    const targetPassword = (password || pin).trim();

    setStaff(prev => prev.map(s => s.name.trim().toLowerCase() === cleanName ? { ...s, pin: pin.trim(), password: targetPassword, username: targetUsername } : s));
    if (currentUser && currentUser.name.trim().toLowerCase() === cleanName) {
      const updatedCurr = { ...currentUser, pin: pin.trim(), password: targetPassword, username: targetUsername };
      setCurrentUser(updatedCurr);
      try {
        sessionStorage.setItem('supabase_bypassed_current_user', JSON.stringify(updatedCurr));
      } catch {}
    }

    if (fbUser) {
      try {
        const uid = fbUser.id || fbUser.uid;
        await supabase.from('user_team_members')
          .update({
            pin: pin.trim(),
            password: targetPassword,
            username: targetUsername
          })
          .eq('userId', uid)
          .eq('name', name);
      } catch (e) {
        console.warn("Supabase credentials update warning:", e);
      }
    }
  };

  const handleRenameRole = (oldRole: string, newRole: string) => {
    const normNew = newRole.trim().toLowerCase();
    if (!normNew) return;
    if (normNew === oldRole) {
      setEditingRoleName(null);
      return;
    }
    if (customRoles.includes(normNew)) {
      showAppToast(`⚠️ የስራ መደቡ "${normNew}" ቀድሞውኑ አለ!`);
      return;
    }
    // 1. Update customRoles
    setCustomRoles(prev => prev.map(r => r === oldRole ? normNew : r));
    // 2. Update staff matching oldRole
    setStaff(prev => prev.map(s => {
      const updated = { ...s };
      if (s.role === oldRole) updated.role = normNew;
      if (s.accessPrivilege === oldRole) updated.accessPrivilege = normNew as any;
      return updated;
    }));
    setEditingRoleName(null);
    showAppToast(`✔ የስራ መደቡ ስም ከ "${oldRole.toUpperCase()}" ወደ "${normNew.toUpperCase()}" በተሳካ ሁኔታ ተቀይሯል!`);
  };

  const handleDeleteRole = (role: string) => {
    askConfirmAndRun(`ይህን የስራ መደብ (${role.toUpperCase()}) በእርግጠኝነት ማጥፋት ይፈልጋሉ?`, () => {
      setCustomRoles(prev => prev.filter(r => r !== role));
      setStaff(prev => prev.map(s => {
        if (s.role === role) {
          return { ...s, role: 'none' };
        }
        return s;
      }));
      showAppToast(`🗑️ የስራ መደብ "${role}" ተወግዷል!`);
    });
  };

  const handleRenamePrivilege = (oldPriv: string, newPriv: string) => {
    const normNew = newPriv.trim().toLowerCase();
    if (!normNew) return;
    if (normNew === oldPriv) {
      setEditingPrivilegeName(null);
      return;
    }
    if (customPrivileges.includes(normNew)) {
      showAppToast(`⚠️ የመዳረሻ ፈቃዱ "${normNew}" ቀድሞውኑ አለ!`);
      return;
    }
    // Update customPrivileges
    setCustomPrivileges(prev => prev.map(p => p === oldPriv ? normNew : p));
    // Update staff matching oldPriv
    setStaff(prev => prev.map(s => {
      const updated = { ...s };
      if (s.accessPrivilege === oldPriv) updated.accessPrivilege = normNew;
      return updated;
    }));
    setEditingPrivilegeName(null);
    showAppToast(`✔ የሲስተም መዳረሻ ፈቃድ ስም ከ "${oldPriv.toUpperCase()}" ወደ "${normNew.toUpperCase()}" በተሳካ ሁኔታ ተቀይሯል!`);
  };

  const handleDeletePrivilege = (priv: string) => {
    askConfirmAndRun(`ይህን የሲስተም መዳረሻ ፈቃድ (${priv.toUpperCase()}) በእርግጠኝነት ማጥፋት ይፈልጋሉ?`, () => {
      setCustomPrivileges(prev => prev.filter(p => p !== priv));
      setStaff(prev => prev.map(s => {
        if (s.accessPrivilege === priv) {
          return { ...s, accessPrivilege: 'none' };
        }
        return s;
      }));
      showAppToast(`🗑️ የሲስተም መዳረሻ ፈቃድ "${priv}" ተወግዷል!`);
    });
  };

  // Atomic helper functions for Assistance Calls to ensure 100% reliable cloud sync without overwriting other clients or creating duplicates
  const addAssistanceCall = async (newCall: AssistanceCall) => {
    const callWithTs: AssistanceCall = {
      ...newCall,
      createdAt: newCall.createdAt || Date.now(),
    };

    setAssistanceCalls(prev => upsertDeduplicatedAssistanceCall(prev, callWithTs));

    try {
      const { data, error: fetchErr } = await supabase
        .from('system_settings')
        .select('value')
        .eq('key', 'assistanceCalls')
        .maybeSingle();

      if (fetchErr) {
        if (fetchErr.code === '42P01' || fetchErr.message?.includes('does not exist')) {
          console.warn("Supabase: Table 'system_settings' is not initialized yet. Staying in local fallback mode.");
        } else {
          console.warn("Error fetching assistanceCalls:", fetchErr);
        }
      }

      let currentList: AssistanceCall[] = [];
      if (!fetchErr && data?.value && Array.isArray(data.value.list)) {
        currentList = data.value.list;
      }

      const updatedList = upsertDeduplicatedAssistanceCall(currentList, callWithTs);
      await supabase
        .from('system_settings')
        .upsert({ key: 'assistanceCalls', value: { list: updatedList } });
    } catch (err) {
      console.warn("Error adding assistance call to DB:", err);
    }
  };

  const resolveOrderAssistanceCalls = async (
    orderId: string,
    handledBy?: string,
    types?: Array<NonNullable<AssistanceCall['type']>>,
  ) => {
    const bareId = orderId.replace(/^#/, '');
    const matchesOrderCall = (c: AssistanceCall) => {
      if (!c.active) return false;
      if (types && types.length > 0 && c.type && !types.includes(c.type)) return false;
      if (c.orderId && (c.orderId === orderId || c.orderId.replace(/^#/, '') === bareId)) return true;
      return c.id.includes(orderId) || c.id.includes(bareId);
    };

    setAssistanceCalls(prev =>
      prev.map(c => (matchesOrderCall(c) ? { ...c, active: false, handledBy: handledBy || c.handledBy } : c))
    );

    try {
      const { data, error: fetchErr } = await supabase
        .from('system_settings')
        .select('value')
        .eq('key', 'assistanceCalls')
        .maybeSingle();
      if (!fetchErr && data?.value && Array.isArray(data.value.list)) {
        const updatedList = (data.value.list as AssistanceCall[]).map(c =>
          matchesOrderCall(c) ? { ...c, active: false, handledBy: handledBy || c.handledBy } : c
        );
        await supabase
          .from('system_settings')
          .upsert({ key: 'assistanceCalls', value: { list: updatedList } });
      }
    } catch (err) {
      console.warn("Error resolving order assistance calls in DB:", err);
    }
  };

  const removeAssistanceCall = async (id: string) => {
    const localTarget = assistanceCalls.find(c => c.id === id);
    const localKey = localTarget ? getAssistanceCallDedupKey(localTarget) : null;
    const isSameCallOrKey = (c: AssistanceCall, key: string | null) =>
      c.id === id || (Boolean(key) && c.active !== false && getAssistanceCallDedupKey(c) === key);

    setAssistanceCalls(prev =>
      prev.map(c => (isSameCallOrKey(c, localKey) ? { ...c, active: false, handledBy: currentUser?.name || c.handledBy } : c))
    );

    try {
      const { data, error: fetchErr } = await supabase
        .from('system_settings')
        .select('value')
        .eq('key', 'assistanceCalls')
        .maybeSingle();

      if (fetchErr) {
        if (fetchErr.code === '42P01' || fetchErr.message?.includes('does not exist')) {
          console.warn("Supabase: Table 'system_settings' is not initialized yet. Staying in local fallback mode.");
        } else {
          console.warn("Error fetching assistanceCalls:", fetchErr);
        }
      }

      let currentList: AssistanceCall[] = [];
      if (!fetchErr && data?.value && Array.isArray(data.value.list)) {
        currentList = data.value.list;
      }

      const remoteTarget = currentList.find(c => c.id === id) || localTarget;
      const remoteKey = remoteTarget ? getAssistanceCallDedupKey(remoteTarget) : localKey;

      const updatedList = currentList.map(c =>
        isSameCallOrKey(c, remoteKey) ? { ...c, active: false, handledBy: currentUser?.name || c.handledBy } : c
      );
      await supabase
        .from('system_settings')
        .upsert({ key: 'assistanceCalls', value: { list: updatedList } });
    } catch (err) {
      console.warn("Error resolving assistance call in DB:", err);
    }
  };

  const markAssistanceCallInactive = async (id: string) => {
    await removeAssistanceCall(id);
  };

  // CALL FOR ASSISTANCE / TARGETED ASSIGNED WAITER & LEADERSHIP CONCIERGE
